import json
import itertools

def solve_puzzle():
    # Houses numbered left (1) to right (3)
    houses = [1, 2, 3]

    # Attributes as given in the puzzle
    names = ["Eric", "Arnold", "Peter"]
    smoothies = ["desert", "watermelon", "cherry"]
    book_genres = ["science fiction", "romance", "mystery"]

    solutions = []

    for name_perm in itertools.permutations(names):
        # Clue 5: Peter is in the first house.
        if name_perm[0] != "Peter":
            continue

        for smoothie_perm in itertools.permutations(smoothies):
            for book_perm in itertools.permutations(book_genres):
                # Build index lookups
                idx_name = {name_perm[i]: i for i in range(3)}
                idx_smoothie = {smoothie_perm[i]: i for i in range(3)}
                idx_book = {book_perm[i]: i for i in range(3)}

                # Clue 1: Cherry smoothie left of the person who loves mystery books.
                if not (idx_smoothie["cherry"] < idx_book["mystery"]):
                    continue

                # Clue 2: Arnold is the person who loves mystery books.
                if idx_name["Arnold"] != idx_book["mystery"]:
                    continue

                # Clue 3: Science fiction not in the first house.
                if book_perm[0] == "science fiction":
                    continue

                # Clue 4: Desert smoothie lover is directly left of the person who loves mystery books.
                if not (idx_smoothie["desert"] + 1 == idx_book["mystery"]):
                    continue

                # If all constraints met, record solution
                solutions.append((name_perm, smoothie_perm, book_perm))

    if len(solutions) != 1:
        raise ValueError(f"Expected exactly one solution, found {len(solutions)}")

    name_perm, smoothie_perm, book_perm = solutions[0]

    header = ["House", "Name", "favorite smoothie", "favorite book genres"]
    rows = []
    for i in range(3):
        row = [str(houses[i]), name_perm[i], smoothie_perm[i], book_perm[i]]
        rows.append(row)

    return {"solution": {"header": header, "rows": rows}}

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
